# owner: platform
import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def make_shift(worker, day, start, end):
    return Shift(worker, day, Span(start, end))


class TimesheetRowsTests(unittest.TestCase):
    def test_busiest_first(self):
        rows = timesheet_rows([
            make_shift("Ana", "mon", 540, 600),
            make_shift("Brisa", "mon", 540, 840),
            make_shift("Brisa", "tue", 540, 660)
        ])
        self.assertEqual(rows, [
            "Brisa: 2 shifts, 7.0 hours",
            "Ana: 1 shift, 1.0 hours"
        ])

    def test_one_decimal_place(self):
        rows = timesheet_rows([
            make_shift("Ana", "mon", 540, 625)
        ])
        self.assertEqual(rows, ["Ana: 1 shift, 1.4 hours"])

    def test_ties_sorted_by_name(self):
        rows = timesheet_rows([
            make_shift("Zed", "mon", 540, 600),
            make_shift("Ana", "tue", 540, 600)
        ])
        self.assertTrue(rows[0].startswith("Ana"))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([
                make_shift("  ", "mon", 540, 600)
            ])
